sys_script.script:
(function executeRule(current, previous /* null when async */) {

    var patientSysId = current.getValue('patient');

    // Patient itself is mandatory on the form, but this protects
    // the server-side rule as well.
    if (gs.nil(patientSysId)) {
        gs.addErrorMessage('Patient is required for an AI Insight.');
        current.setAbortAction(true);
        return;
    }

    /*
     * Validate Admission → Patient relationship.
     */
    if (!gs.nil(current.getValue('admission'))) {

        var admission = current.admission.getRefRecord();

        if (!admission.isValidRecord()) {
            gs.addErrorMessage(
                'The selected Admission is not valid.'
            );

            current.setAbortAction(true);
            return;
        }

        var admissionPatient = admission.getValue('patient');

        if (!gs.nil(admissionPatient) &&
            admissionPatient != patientSysId) {

            gs.addErrorMessage(
                'The selected Admission does not belong to the selected Patient.'
            );

            current.setAbortAction(true);
            return;
        }
    }

    /*
     * Validate Care Plan → Patient relationship.
     */
    if (!gs.nil(current.getValue('care_plan'))) {

        var carePlan = current.care_plan.getRefRecord();

        if (!carePlan.isValidRecord()) {
            gs.addErrorMessage(
                'The selected Care Plan is not valid.'
            );

            current.setAbortAction(true);
            return;
        }

        var carePlanPatient = carePlan.getValue('patient');

        if (!gs.nil(carePlanPatient) &&
            carePlanPatient != patientSysId) {

            gs.addErrorMessage(
                'The selected Care Plan does not belong to the selected Patient.'
            );

            current.setAbortAction(true);
            return;
        }
    }

})(current, previous);
